# ----------------- 1) Query base: items con Description e ID -----------------
query = '''
    SELECT Description, ID
    FROM papoitem
    WHERE PapoID=?
'''
db = value["db"]
papoID = value["papoID"]
nodeID = value["nodeID"]
args = [papoID]

results = system.db.runPrepQuery(query, args, db)
ds = system.dataset.toDataSet(results)

# ----------------- 2) Traer registros (JSON en DataAnswer) ORDENADOS --------
query = '''
    SELECT DataAnswer
    FROM registerhistory
    WHERE PapoID=? AND RegisterCode=? AND NodeID=? AND RegisterTypeID <> 10
    ORDER BY ID ASC
'''
RegisterCode = value["registerCode"]
args = [papoID, RegisterCode, nodeID]
registerRows = system.db.runPrepQuery(query, args, db)
registerRows = system.dataset.toDataSet(registerRows)  # asegúrate de poder usar getValueAt("DataAnswer")

# ----------------- 3) Utilidades --------------------------------------------
REGISTER_TYPE_NAMES = {
    1: u"Una hora",
    2: u"Dos horas",
    3: u"Media hora",
    4: u"Cuatro horas",
    5: u"Cambio de referencia",
    6: u"Mantenimiento",
    7: u"Inicio de turno",
    8: u"Fin de turno",
    9: u"Mitad de turno",
    11: u"Diario",
    14: u"Control de rechazos",
    15: u"Hallazgos",
	16: u"Ing. Baterías"
}

dia_semana = str(system.date.format(system.date.now() , "EEEE") )
dia_semana = dia_semana.capitalize()

REGISTER_TYPE_NAMES[11] = dia_semana

def _coerce_int(x):
    try: return int(x)
    except: return x

def _to_str_or_none(v):
    if v is None: return None
    try: return unicode(v)
    except:
        try: return str(v)
        except: return u""

def unique_col_name(baseName, dsIn):
    existing = [dsIn.getColumnName(i) for i in range(dsIn.getColumnCount())]
    if baseName not in existing: return baseName
    i = 2
    while True:
        name = u"{} ({})".format(baseName, i)
        if name not in existing: return name
        i += 1

def _append_column_rebuild(dsIn, colName, colValues):
    colCount = dsIn.getColumnCount()
    names = [dsIn.getColumnName(i) for i in range(colCount)]
    try: descIdx = names.index("Description")
    except ValueError: descIdx = 0
    headers = ["Description", colName] + [n for i,n in enumerate(names) if i!=descIdx]
    newRows = []
    for r in range(dsIn.getRowCount()):
        descVal = dsIn.getValueAt(r, descIdx)
        newVal  = _to_str_or_none(colValues[r] if r < len(colValues) else None)
        rest    = [dsIn.getValueAt(r, i) for i in range(colCount) if i!=descIdx]
        newRows.append([descVal, newVal] + rest)
    return system.dataset.toDataSet(headers, newRows)

# ---------- parseo robusto de timestamp (incluye "Sep 17, 2025, 4:09:33 PM") ----------
def _parse_timestamp_to_ms(ts):
    if ts is None: return None

    # numérico (epoch s/ms)
    try:
        v = None
        if isinstance(ts, (int, long, float)):
            v = long(ts)
        else:
            s = unicode(ts).strip()
            if s.replace('.', '', 1).isdigit():
                v = long(float(s))
        if v is not None:
            return long(v*1000) if v < 1000000000000 else long(v)
    except:
        pass

    try:
        s = unicode(ts).strip()
    except:
        return None

    from java.text import SimpleDateFormat
    from java.util import Locale
    patterns = [
        # ISO
        "yyyy-MM-dd'T'HH:mm:ss.SSSX",
        "yyyy-MM-dd'T'HH:mm:ssX",
        "yyyy-MM-dd HH:mm:ss",
        "yyyy/MM/dd HH:mm:ss",
        "dd/MM/yyyy HH:mm:ss",
        "EEE MMM dd HH:mm:ss zzz yyyy",  # estilo Java Date.toString
        # >>> Formatos de tu captura (Locale.US)
        "MMM d, yyyy, h:mm:ss a",
        "MMM dd, yyyy, h:mm:ss a",
        "MMM d, yyyy, hh:mm:ss a",
        "MMM dd, yyyy, hh:mm:ss a",
    ]
    for p in patterns:
        try:
            sdf = SimpleDateFormat(p, Locale.US)
            sdf.setLenient(True)
            dt = sdf.parse(s)
            return long(dt.getTime())
        except:
            pass
    return None

def _extract_last_timestamp_ms(jsonObj):
    items = jsonObj.get("items", jsonObj) if isinstance(jsonObj, dict) else jsonObj
    if not items or not isinstance(items, (list, tuple)): return None
    last = items[-1] if isinstance(items[-1], dict) else {}
    ts = None
    if isinstance(last, dict):
        ts = last.get("timestamp", last.get("Timestamp", last.get("time")))
    return _parse_timestamp_to_ms(ts)

def last_register_type_id(jsonObj):
    items = jsonObj.get("items", jsonObj) if isinstance(jsonObj, dict) else jsonObj
    if not items: return None
    last = items[-1]
    return last.get("registerTypeID", None) if isinstance(last, dict) else None

# ----------------- 4) Agrupador con corte por tiempo (>3 s) ------------------
def build_grouped_jsons(rowsDS):
    FLUSH_GAP_MS = 3000
    out = []
    state = {"rtid": None, "map": {}, "meta": {}, "ts": None}
    counts = {}  # rtid -> grupos emitidos

    def _base_name(rtid):
        return REGISTER_TYPE_NAMES.get(rtid, u"Tipo {}".format(rtid if rtid is not None else u"desconocido"))

    def _flush():
        if state["rtid"] is None: return
        rtid = state["rtid"]
        n = counts.get(rtid, 0) + 1
        counts[rtid] = n
        colName = _base_name(rtid) if n == 1 else u"{} ({})".format(_base_name(rtid), n)

        items_list = []
        for pid, ans in state["map"].items():
            items_list.append({"papoItemID": pid, "answer": ans, "registerTypeID": rtid})

        meta = {"insights":"", "registerTypeID": rtid, "groupIndex": n, "colName": colName}
        try:
            u = state["meta"].get("user") or state["meta"].get("User")
            if u is not None: meta["user"] = u
            t = state["meta"].get("timestamp") or state["meta"].get("Timestamp") or state["meta"].get("time")
            if t is not None: meta["timestamp"] = t
        except: pass
        items_list.append(meta)

        out.append({"json": system.util.jsonEncode({"items": items_list}), "colName": colName})

        # reset
        state["rtid"] = None
        state["map"]  = {}
        state["meta"] = {}
        state["ts"]   = None

    for i in range(rowsDS.getRowCount()):
        jsonStr = rowsDS.getValueAt(i, "DataAnswer")
        if not jsonStr: continue
        try:
            data = system.util.jsonDecode(jsonStr)
        except:
            continue

        items = data.get("items", data) if isinstance(data, dict) else data
        if not isinstance(items, (list, tuple)) or not items: continue

        rtid = last_register_type_id(data)
        tsms = _extract_last_timestamp_ms(data)

        # cortar por cambio de tipo o por gap > 3 s
        if (rtid != state["rtid"]) or (state["ts"] is not None and tsms is not None and abs(tsms - state["ts"]) > FLUSH_GAP_MS):
            _flush()
            state["rtid"] = rtid

        # meta del último item original
        last = items[-1] if isinstance(items[-1], dict) else {}
        if isinstance(last, dict):
            if "user" in last or "User" in last:
                state["meta"]["user"] = last.get("user", last.get("User"))
            if ("timestamp" in last) or ("Timestamp" in last) or ("time" in last):
                state["meta"]["timestamp"] = last.get("timestamp", last.get("Timestamp", last.get("time")))

        # acumular respuestas sin duplicar papoItemID en el grupo
        for it in items:
            if isinstance(it, dict) and "papoItemID" in it:
                pid = _coerce_int(it["papoItemID"])
                if pid not in state["map"]:
                    state["map"][pid] = it.get("answer", None)

        if tsms is not None:
            state["ts"] = tsms

    _flush()
    return out

# ----------------- 5) Crear columnas (una por grupo) -------------------------
def col_name_from_json(jsonObj):
    items = jsonObj.get("items", jsonObj) if isinstance(jsonObj, dict) else jsonObj
    if not items: return u"Sin tipo"
    last = items[-1] if isinstance(items[-1], dict) else {}
    if isinstance(last, dict) and last.get("colName"):
        try: return unicode(last.get("colName"))
        except: return str(last.get("colName"))
    # fallback
    rt = last.get("registerTypeID", None) if isinstance(last, dict) else None
    base = REGISTER_TYPE_NAMES.get(rt, u"Tipo {}".format(rt if rt is not None else u"desconocido"))
    gi = 1
    try: gi = int(last.get("groupIndex", 1))
    except: gi = 1
    return base if gi == 1 else u"{} ({})".format(base, gi)

def add_column_from_json(dsIn, jsonStr, idCol="ID", overrideColName=None):
    if not jsonStr: return dsIn
    try:
        data = system.util.jsonDecode(jsonStr)
    except:
        return dsIn

    baseName = overrideColName if overrideColName else col_name_from_json(data)
    colName  = unique_col_name(baseName, dsIn)

    items = data.get("items", data) if isinstance(data, dict) else data
    if not isinstance(items, (list, tuple)): return dsIn

    id_to_answer = {}
    for it in items:
        if isinstance(it, dict) and "papoItemID" in it:
            pid = _coerce_int(it["papoItemID"])
            id_to_answer[pid] = it.get("answer", None)

    newCol = []
    for r in range(dsIn.getRowCount()):
        try: rowID = _coerce_int(dsIn.getValueAt(r, idCol))
        except: rowID = None
        newCol.append(id_to_answer.get(rowID, None))

    return _append_column_rebuild(dsIn, colName, newCol)

grouped = build_grouped_jsons(registerRows)
for g in grouped:
    ds = add_column_from_json(ds, g["json"], idCol="ID", overrideColName=g["colName"])

# ----------------- 6) Filas Usuario / Fecha de registro ----------------------
def _extract_json_payload(g): return g.get("json")

def prepend_timestamp_row(dsIn, groups):
    colCount = dsIn.getColumnCount()
    headers  = [dsIn.getColumnName(i) for i in range(colCount)]
    type_cols = [h for h in headers if h not in ("Description", "ID")]

    def _ts(jsonStr):
        try: data = system.util.jsonDecode(jsonStr)
        except: return None
        items = data.get("items", data) if isinstance(data, dict) else data
        if not items or not isinstance(items, (list, tuple)): return None
        last = items[-1]
        if isinstance(last, dict):
            return last.get("timestamp", last.get("Timestamp", last.get("time")))
        return None

    ts_in_creation = [_ts(_extract_json_payload(g)) for g in groups]
    ts_in_display  = list(reversed(ts_in_creation))

    if len(ts_in_display) < len(type_cols):
        ts_in_display += [None] * (len(type_cols) - len(ts_in_display))
    else:
        ts_in_display = ts_in_display[:len(type_cols)]

    newRow = []
    for h in headers:
        if h == "Description": newRow.append(u"Fecha de registro")
        elif h == "ID":        newRow.append(None)
        elif h in type_cols:   newRow.append(_to_str_or_none(ts_in_display[type_cols.index(h)]))
        else:                  newRow.append(None)

    rows = [newRow] + [[dsIn.getValueAt(r, c) for c in range(colCount)] for r in range(dsIn.getRowCount())]
    return system.dataset.toDataSet(headers, rows)

def append_user_row(dsIn, groups):
    colCount = dsIn.getColumnCount()
    headers  = [dsIn.getColumnName(i) for i in range(colCount)]
    type_cols = [h for h in headers if h not in ("Description", "ID")]

    def _user(jsonStr):
        try: data = system.util.jsonDecode(jsonStr)
        except: return None
        items = data.get("items", data) if isinstance(data, dict) else data
        if not items or not isinstance(items, (list, tuple)): return None
        last = items[-1]
        if isinstance(last, dict):
            return last.get("user", last.get("User"))
        return None

    users_in_creation = [_user(_extract_json_payload(g)) for g in groups]
    users_in_display  = list(reversed(users_in_creation))

    if len(users_in_display) < len(type_cols):
        users_in_display += [None] * (len(type_cols) - len(users_in_display))
    else:
        users_in_display = users_in_display[:len(type_cols)]

    newRow = []
    for h in headers:
        if h == "Description": newRow.append(u"Usuario")
        elif h == "ID":        newRow.append(None)
        elif h in type_cols:   newRow.append(_to_str_or_none(users_in_display[type_cols.index(h)]))
        else:                  newRow.append(None)

    rows = [newRow] + [[dsIn.getValueAt(r, c) for c in range(colCount)] for r in range(dsIn.getRowCount())]
    return system.dataset.toDataSet(headers, rows)

# Inserta filas (primero fecha, luego usuario)
ds = prepend_timestamp_row(ds, grouped)
ds = append_user_row(ds, grouped)

	# Filter out rows with Description == "Observaciones"
headers = [ds.getColumnName(i) for i in range(ds.getColumnCount())]
newRows = []

for r in range(ds.getRowCount()):
    if ds.getValueAt(r, "Description") != u"Observaciones":
        newRows.append([ds.getValueAt(r, c) for c in range(ds.getColumnCount())])

# Build the new dataset
ds = system.dataset.toDataSet(headers, newRows)

return ds

