customMethods.script:
"""
Build preview table dataset from registerhistory answers.

Queries papoitem for form questions, fetches DataAnswer records,
groups them by RegisterTypeID with time-gap splitting (3s),
and builds a dynamic dataset with one column per register group.
Prepends Usuario and Fecha rows.

Version: 2.0.0

Args:
	self (Component): Reference to root component

Returns:
	DataSet: Table with Description + one column per register group

Changelog:
	2026-07-06 | William | v1.0.0 - Original version
	2026-07-06 | William | v2.0.0 - Cleaned up, camelCase, optimized
"""

db = self.view.custom.dbConnection
papoID = self.view.params.papoID
nodeID = self.view.params.nodeID
workstationnodeID = self.view.params.workstationnodeID

# Register type display names
REGISTER_TYPE_NAMES = {
	1: u"Una hora",
	2: u"Dos horas",
	3: u"Media hora",
	4: u"Cuatro horas",
	5: u"Cambio de referencia",
	6: u"Mantenimiento",
	7: u"Inicio",
	8: u"Fin",
	9: u"Mitad de turno",
	11: u"Diario",
	14: u"Control de rechazos",
	15: u"Hallazgos",
	16: u"Ing. Baterías",
	17: u"Sal. Baterías",
	18: u"Defectos",
	19: u"Paro",
	20: u"Barcada"
}

# Override "Diario" with current day name
dayName = str(system.date.format(system.date.now(), "EEEE")).capitalize()
REGISTER_TYPE_NAMES[11] = dayName

# Fill policy for missing answers
FILL_POLICY = "blank"

# Time gap threshold for grouping (ms)
FLUSH_GAP_MS = 3000


# ---- Utility functions ----

def coerceInt(x):
	"""Try converting to int, return as-is if not possible."""
	try:
		return int(x)
	except:
		return x


def toStrOrNone(v):
	"""Convert any value to unicode/str for dataset compatibility."""
	if v is None:
		return None
	try:
		return unicode(v)
	except:
		try:
			return str(v)
		except:
			return u""


def uniqueColName(baseName, dsIn):
	"""Generate unique column name avoiding duplicates."""
	existing = [dsIn.getColumnName(i) for i in range(dsIn.getColumnCount())]
	if baseName not in existing:
		return baseName
	i = 2
	while True:
		name = u"{} ({})".format(baseName, i)
		if name not in existing:
			return name
		i += 1


def hasAnswerField(it):
	"""Check if item dict has a valid answer field."""
	return isinstance(it, dict) and "answer" in it and it["answer"] is not None


def normalizeAnswer(val):
	"""Normalize answer value for storage."""
	if val is False:
		return False
	if val is None:
		return None
	try:
		return unicode(val)
	except:
		try:
			return str(val)
		except:
			return u""


def applyFillPolicy(currentValue, rowIdx, dsIn):
	"""Apply fill policy for missing answer values."""
	if currentValue is not None:
		return currentValue
	if FILL_POLICY == "null":
		return None
	if FILL_POLICY == "blank":
		return u""
	if FILL_POLICY == "dash":
		return u"\u2014"
	if FILL_POLICY == "prev":
		cols = dsIn.getColumnCount()
		names = [dsIn.getColumnName(i) for i in range(cols)]
		for c in range(cols):
			if names[c] in ("Description", "ID"):
				continue
			try:
				v = dsIn.getValueAt(rowIdx, c)
				if v is not None and unicode(v).strip() != u"":
					return v
			except:
				pass
		return None
	return None


# ---- Timestamp parsing ----

def parseTimestampToMs(ts):
	"""Parse various timestamp formats to epoch milliseconds."""
	if ts is None:
		return None

	# Numeric (epoch s/ms)
	try:
		v = None
		if isinstance(ts, (int, long, float)):
			v = long(ts)
		else:
			s = unicode(ts).strip()
			if s.replace('.', '', 1).isdigit():
				v = long(float(s))
		if v is not None:
			return long(v * 1000) if v < 1000000000000 else long(v)
	except:
		pass

	try:
		s = unicode(ts).strip()
	except:
		return None

	from java.text import SimpleDateFormat
	from java.util import Locale
	patterns = [
		"yyyy-MM-dd'T'HH:mm:ss.SSSX",
		"yyyy-MM-dd'T'HH:mm:ssX",
		"yyyy-MM-dd HH:mm:ss",
		"yyyy/MM/dd HH:mm:ss",
		"dd/MM/yyyy HH:mm:ss",
		"EEE MMM dd HH:mm:ss zzz yyyy",
		"MMM d, yyyy, h:mm:ss a",
		"MMM dd, yyyy, h:mm:ss a",
		"MMM d, yyyy, hh:mm:ss a",
		"MMM dd, yyyy, hh:mm:ss a",
	]
	for p in patterns:
		try:
			sdf = SimpleDateFormat(p, Locale.US)
			sdf.setLenient(True)
			dt = sdf.parse(s)
			return long(dt.getTime())
		except:
			pass
	return None


def extractLastTimestampMs(jsonObj):
	"""Extract timestamp from last item in JSON."""
	items = jsonObj.get("items", jsonObj) if isinstance(jsonObj, dict) else jsonObj
	if not items or not isinstance(items, (list, tuple)):
		return None
	last = items[-1] if isinstance(items[-1], dict) else {}
	if isinstance(last, dict):
		ts = last.get("timestamp", last.get("Timestamp", last.get("time")))
		return parseTimestampToMs(ts)
	return None


def lastRegisterTypeId(jsonObj):
	"""Get registerTypeID from last item in JSON."""
	items = jsonObj.get("items", jsonObj) if isinstance(jsonObj, dict) else jsonObj
	if not items:
		return None
	last = items[-1]
	return last.get("registerTypeID", None) if isinstance(last, dict) else None


# ---- Dataset column operations ----

def appendColumnRebuild(dsIn, colName, colValues):
	"""Insert new column at position 2 (after Description), rebuilding DataSet."""
	colCount = dsIn.getColumnCount()
	names = [dsIn.getColumnName(i) for i in range(colCount)]

	try:
		descIdx = names.index("Description")
	except ValueError:
		descIdx = 0

	headers = ["Description", colName] + [n for i, n in enumerate(names) if i != descIdx]

	newRows = []
	for r in range(dsIn.getRowCount()):
		descVal = dsIn.getValueAt(r, descIdx)
		newVal = toStrOrNone(colValues[r] if r < len(colValues) else None)
		rest = [dsIn.getValueAt(r, i) for i in range(colCount) if i != descIdx]
		newRows.append([descVal, newVal] + rest)

	return system.dataset.toDataSet(headers, newRows)


def addColumnFromJson(dsIn, jsonStr, idCol="ID", overrideColName=None):
	"""Add a column to dataset from a DataAnswer JSON string."""
	if not jsonStr:
		return dsIn
	try:
		data = system.util.jsonDecode(jsonStr)
	except:
		return dsIn

	# Determine column name
	if overrideColName:
		baseName = overrideColName
	else:
		items = data.get("items", data) if isinstance(data, dict) else data
		if not items:
			return dsIn
		last = items[-1] if isinstance(items[-1], dict) else {}
		if isinstance(last, dict) and last.get("colName"):
			try:
				baseName = unicode(last.get("colName"))
			except:
				baseName = str(last.get("colName"))
		else:
			rt = last.get("registerTypeID", None) if isinstance(last, dict) else None
			base = REGISTER_TYPE_NAMES.get(rt, u"Tipo {}".format(rt if rt is not None else u"desconocido"))
			gi = 1
			try:
				gi = int(last.get("groupIndex", 1))
			except:
				gi = 1
			baseName = base if gi == 1 else u"{} ({})".format(base, gi)

	colName = uniqueColName(baseName, dsIn)

	items = data.get("items", data) if isinstance(data, dict) else data
	if not isinstance(items, (list, tuple)):
		return dsIn

	# Build answer map: papoItemID -> answer
	idToAnswer = {}
	for it in items:
		if isinstance(it, dict) and "papoItemID" in it:
			pid = coerceInt(it["papoItemID"])
			if hasAnswerField(it):
				idToAnswer[pid] = normalizeAnswer(it["answer"])
			else:
				idToAnswer[pid] = None

	# Build column aligned to dataset by ID
	newCol = []
	for r in range(dsIn.getRowCount()):
		try:
			rowID = coerceInt(dsIn.getValueAt(r, idCol))
		except:
			rowID = None
		raw = idToAnswer[rowID] if rowID in idToAnswer else None
		filled = applyFillPolicy(raw, r, dsIn)
		newCol.append(filled)

	return appendColumnRebuild(dsIn, colName, newCol)


# ---- Grouping by RegisterTypeID with time-gap splitting ----

def buildGroupedJsons(rowsDS):
	"""Group consecutive records by RegisterTypeID, split on >3s gap."""
	out = []
	state = {"rtid": None, "map": {}, "meta": {}, "ts": None}
	counts = {}

	def baseName(rtid):
		return REGISTER_TYPE_NAMES.get(rtid, u"Tipo {}".format(rtid if rtid is not None else u"desconocido"))

	def flush():
		if state["rtid"] is None:
			return
		rtid = state["rtid"]
		n = counts.get(rtid, 0) + 1
		counts[rtid] = n
		colName = baseName(rtid) if n == 1 else u"{} ({})".format(baseName(rtid), n)

		itemsList = []
		for pid, ans in state["map"].items():
			itemsList.append({"papoItemID": pid, "answer": ans, "registerTypeID": rtid})

		meta = {"insights": "", "registerTypeID": rtid, "groupIndex": n, "colName": colName}
		try:
			u = state["meta"].get("user") or state["meta"].get("User")
			if u is not None:
				meta["user"] = u
			t = state["meta"].get("timestamp") or state["meta"].get("Timestamp") or state["meta"].get("time")
			if t is not None:
				meta["timestamp"] = t
		except:
			pass
		itemsList.append(meta)

		out.append({"json": system.util.jsonEncode({"items": itemsList}), "colName": colName})

		# Reset state
		state["rtid"] = None
		state["map"] = {}
		state["meta"] = {}
		state["ts"] = None

	for i in range(rowsDS.getRowCount()):
		jsonStr = rowsDS.getValueAt(i, "DataAnswer")
		if not jsonStr:
			continue
		try:
			data = system.util.jsonDecode(jsonStr)
		except:
			continue

		items = data.get("items", data) if isinstance(data, dict) else data
		if not isinstance(items, (list, tuple)) or not items:
			continue

		rtid = lastRegisterTypeId(data)
		tsms = extractLastTimestampMs(data)

		# Flush on type change or time gap > 3s
		if (rtid != state["rtid"]) or (state["ts"] is not None and tsms is not None and abs(tsms - state["ts"]) > FLUSH_GAP_MS):
			flush()
			state["rtid"] = rtid

		# Capture metadata from last item
		last = items[-1] if isinstance(items[-1], dict) else {}
		if isinstance(last, dict):
			if "user" in last or "User" in last:
				state["meta"]["user"] = last.get("user", last.get("User"))
			if "timestamp" in last or "Timestamp" in last or "time" in last:
				state["meta"]["timestamp"] = last.get("timestamp", last.get("Timestamp", last.get("time")))

		# Accumulate answers without duplicating papoItemID
		for it in items:
			if isinstance(it, dict) and "papoItemID" in it:
				pid = coerceInt(it["papoItemID"])
				if pid not in state["map"]:
					if hasAnswerField(it):
						state["map"][pid] = normalizeAnswer(it["answer"])
					else:
						state["map"][pid] = None

		if tsms is not None:
			state["ts"] = tsms

	flush()
	return out


