def extractJsonPayload(g):
	return g.get("json")


def prependTimestampRow(dsIn, groups):
	"""Insert Fecha de registro row at top."""
	colCount = dsIn.getColumnCount()
	headers = [dsIn.getColumnName(i) for i in range(colCount)]
	typeCols = [h for h in headers if h not in ("Description", "ID")]

	def getTs(jsonStr):
		try:
			data = system.util.jsonDecode(jsonStr)
		except:
			return None
		items = data.get("items", data) if isinstance(data, dict) else data
		if not items or not isinstance(items, (list, tuple)):
			return None
		last = items[-1]
		if isinstance(last, dict):
			return last.get("timestamp", last.get("Timestamp", last.get("time")))
		return None

	tsCreation = [getTs(extractJsonPayload(g)) for g in groups]
	tsDisplay = list(reversed(tsCreation))

	# Align sizes
	if len(tsDisplay) < len(typeCols):
		tsDisplay += [None] * (len(typeCols) - len(tsDisplay))
	else:
		tsDisplay = tsDisplay[:len(typeCols)]

	newRow = []
	for h in headers:
		if h == "Description":
			newRow.append(u"Fecha de registro")
		elif h == "ID":
			newRow.append(None)
		elif h in typeCols:
			newRow.append(toStrOrNone(tsDisplay[typeCols.index(h)]))
		else:
			newRow.append(None)

	rows = [newRow] + [[dsIn.getValueAt(r, c) for c in range(colCount)] for r in range(dsIn.getRowCount())]
	return system.dataset.toDataSet(headers, rows)


