# 1) Query base items ordered by register type priority
query = '''
	SELECT Description, ID
	FROM papoitem
	WHERE PapoID = ?
	ORDER BY CHARINDEX(
		CAST(RegisterTypeID AS VARCHAR),
		'7,3,1,2,4,5,6,9,10,11,14,15,16,17,18,19,20,8'
	), ID
'''
results = system.db.runPrepQuery(query, [papoID], db)
ds = system.dataset.toDataSet(results)

# 2) Get last RegisterCode
query = '''
	SELECT TOP 1 RegisterCode
	FROM registerhistory
	WHERE PapoID = ? AND WorkStationNodeID = ?
	ORDER BY RegisterCode DESC
'''
rcResult = system.db.runPrepQuery(query, [papoID, workstationnodeID], db)
registerCode = rcResult.getValueAt(0, 0)

# 3) Fetch DataAnswer records for this cycle
query = '''
	SELECT DataAnswer
	FROM registerhistory
	WHERE PapoID = ? AND RegisterCode = ? AND NodeID = ? AND RegisterTypeID <> 10
	ORDER BY ID ASC
'''
registerRows = system.db.runPrepQuery(query, [papoID, registerCode, nodeID], db)
registerRows = system.dataset.toDataSet(registerRows)

# 4) Group by RegisterTypeID and build columns
grouped = buildGroupedJsons(registerRows)
for g in grouped:
	ds = addColumnFromJson(ds, g["json"], idCol="ID", overrideColName=g["colName"])

# 5) Prepend metadata rows (timestamp first, then user on top)
ds = prependTimestampRow(ds, grouped)
ds = prependUserRow(ds, grouped)

# 6) Filter out "Observaciones" rows
headers = [ds.getColumnName(i) for i in range(ds.getColumnCount())]
newRows = []
for r in range(ds.getRowCount()):
	if ds.getValueAt(r, "Description") != u"Observaciones":
		newRows.append([ds.getValueAt(r, c) for c in range(ds.getColumnCount())])

ds = system.dataset.toDataSet(headers, newRows)

return ds
